{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT CAST(floor(epoch(time)/10) AS BIGINT)*10 AS bucket, sum(CASE WHEN service_name='ts-travel2-service' AND attr_span_kind='Server' THEN 1 ELSE 0 END) AS travel2_server, sum(CASE WHEN service_name='ts-route-plan-service' AND attr_span_kind='Client' AND attr_status_code='Error' THEN 1 ELSE 0 END) AS rp_err FROM abnormal_traces GROUP BY 1 ORDER BY 1 LIMIT 15",
          "claim": "ts-travel2-service emits no server spans for roughly the first 40-50 s of the incident, then resumes; route-plan client errors occur in the same window."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, count(*) AS n, min(CAST(epoch(time) AS BIGINT)) AS first_ts, max(CAST(epoch(time) AS BIGINT)) AS last_ts FROM abnormal_logs WHERE message LIKE '%Connection refused%' GROUP BY service_name",
          "claim": "74 route-plan SEVERE logs report 'Connection refused' calling ts-travel2-service, all within a ~50 s window."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) AS avg_v, round(max(value),3) AS max_v FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric='container.cpu.usage' GROUP BY metric",
          "claim": "Travel2 container CPU spikes to about 4.6 cores in the incident (max), versus at most 0.33 in normal operation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, c.span_name, count(*) AS n, sum(CASE WHEN NOT EXISTS (SELECT 1 FROM abnormal_traces s WHERE s.parent_span_id=c.span_id AND s.trace_id=c.trace_id) THEN 1 ELSE 0 END) AS no_child_error FROM abnormal_traces c WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND c.attr_status_code='Error' GROUP BY ALL",
          "claim": "Route-plan's failed outgoing POSTs return in about 1 ms with no callee span, consistent with travel2 refusing connections."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, c.attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND c.attr_status_code='Error' GROUP BY ALL",
          "claim": "Travel-plan's 74 failed client calls to route-plan return HTTP 500 with route-plan server spans present."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-travel-plan-service') AND attr_span_kind='Server' AND attr_status_code='Error' GROUP BY ALL ORDER BY n DESC LIMIT 12",
          "claim": "ts-ui-dashboard's travelPlan server spans (minStation, cheapest, quickest) return HTTP 500 in step with travel-plan's failures."
        }
      ]
    }
  ]
}
